/// An organization-scoped audit log export destination.
///
/// Delivery is at-least-once for rows visible when their window is committed: a delivery that is retried rewrites the same object, and the same `event_id` can appear in more than one object, so consumers must deduplicate on `event_id`. Each event-time window is held for ten minutes before it commits; a row that becomes visible after its window is committed may not be delivered.
///
/// Objects are written as `\<prefix\>/destination_id=\<destination\>/org_id=\<org\>/date=\<YYYY-MM-DD\>/hour=\<HH\>/\<window\>-\<chunk\>.jsonl.gz`, where `date` and `hour` are the UTC calendar hour that fully contains every row in the object, so the layout is safe to register as a Hive-partitioned table. The object name is derived from the rows it holds, so a retried delivery rewrites its own object.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct AuditLogExportDestination {
    #[serde(default)]
    pub bucket: String,
    #[serde(default)]
    pub consecutive_failures: i64,
    #[serde(default)]
    pub created_at: chrono::DateTime<chrono::Utc>,
    #[serde(default)]
    pub external_id: String,
    #[serde(default)]
    pub format: String,
    #[serde(default)]
    pub id: String,
    /// The Kernel role that assumes `role_arn` in your account to deliver logs. Allow this role as the principal in your role's trust policy, and require `external_id` as the `sts:ExternalId` condition.
    ///
    /// Recreating a destination issues a new `external_id`, which the trust policy has to be updated to match.
    #[serde(default)]
    pub kernel_role_arn: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kms_key_id: Option<String>,
    /// Sanitized description of the most recent delivery failure.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_error: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_error_at: Option<chrono::DateTime<chrono::Utc>>,
    /// Opaque, versioned checkpoint for forward-only continuous export. This value is not compatible with audit-log list page tokens.
    ///
    /// Delivery starts at the moment the destination is activated, so events recorded before that are not delivered. Pausing stops delivery and resuming starts again from the time of the resume: events recorded while a destination was paused are never exported, and pausing is not a way to defer delivery.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_exported_cursor: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_success_at: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub next_attempt_at: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default)]
    pub prefix: String,
    #[serde(default)]
    pub region: String,
    #[serde(default)]
    pub role_arn: String,
    /// Pausing prevents new delivery attempts. An S3 upload already in progress may complete after the pause response; its rows can appear again after the destination is resumed.
    #[serde(default)]
    pub status: AuditLogExportDestinationStatus,
    #[serde(default)]
    pub r#type: String,
    #[serde(default)]
    pub updated_at: chrono::DateTime<chrono::Utc>,
}

impl AuditLogExportDestination {
    /// Create a `AuditLogExportDestination` with the required fields set.
    #[allow(clippy::too_many_arguments, clippy::new_without_default)]
    pub fn new(
        id: impl Into<String>,
        region: impl Into<String>,
        bucket: impl Into<String>,
        prefix: impl Into<String>,
        role_arn: impl Into<String>,
        external_id: impl Into<String>,
        kernel_role_arn: impl Into<String>,
        status: impl Into<AuditLogExportDestinationStatus>,
        consecutive_failures: impl Into<i64>,
        created_at: impl Into<chrono::DateTime<chrono::Utc>>,
        updated_at: impl Into<chrono::DateTime<chrono::Utc>>,
    ) -> Self {
        Self {
            bucket: bucket.into(),
            consecutive_failures: consecutive_failures.into(),
            created_at: created_at.into(),
            external_id: external_id.into(),
            format: "jsonl.gz".to_owned(),
            id: id.into(),
            kernel_role_arn: kernel_role_arn.into(),
            kms_key_id: None,
            last_error: None,
            last_error_at: None,
            last_exported_cursor: None,
            last_success_at: None,
            next_attempt_at: None,
            prefix: prefix.into(),
            region: region.into(),
            role_arn: role_arn.into(),
            status: status.into(),
            r#type: "s3".to_owned(),
            updated_at: updated_at.into(),
        }
    }
}

crate::string_enum! {
    /// Pausing prevents new delivery attempts. An S3 upload already in progress may complete after the pause response; its rows can appear again after the destination is resumed.
    AuditLogExportDestinationStatus {
        Active = "active",
        Paused = "paused",
    }
}

