/// Initial browser window size in pixels with optional refresh rate.
/// If omitted, image defaults apply (1920x1080@25).
/// For GPU images, the default is 1920x1080@60.
/// Arbitrary viewport dimensions and refresh rates are accepted.
/// Known-good presets include:
/// 2560x1440@10, 1920x1080@25, 1920x1200@25, 1440x900@25, 1280x800@60, 1024x768@60, 1200x800@60, 768x1024@60, 390x844@60.
/// For GPU images, recommended presets use one of these resolutions with refresh rates 60, 30, 25, or 10:
/// 800x600, 960x720, 1024x576, 1024x768, 1152x648, 1200x800, 1280x720, 1368x768, 1440x900, 1600x900, 1920x1080, 1920x1200, 390x844, 360x250, 768x1024, 800x1600.
/// Viewports outside this list may exhibit unstable live view or recording behavior.
/// If refresh_rate is not provided, it will be automatically determined based on the resolution
/// (higher resolutions use lower refresh rates to keep bandwidth reasonable).
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct BrowserViewport {
    /// Browser window height in pixels. Any positive integer is accepted.
    #[serde(default)]
    pub height: i64,
    /// Display refresh rate in Hz. Any positive integer is accepted; if omitted, automatically determined from width and height.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub refresh_rate: Option<i64>,
    /// Browser window width in pixels. Any positive integer is accepted.
    #[serde(default)]
    pub width: i64,
}

impl BrowserViewport {
    /// Create a `BrowserViewport` with the required fields set.
    #[allow(clippy::too_many_arguments, clippy::new_without_default)]
    pub fn new(width: impl Into<i64>, height: impl Into<i64>) -> Self {
        Self {
            height: height.into(),
            refresh_rate: None,
            width: width.into(),
        }
    }
}

/// An agent-driven HTTP call that drives the browser, handled by the in-VM API server. Calls that manage the VM instead emit platform_api_call.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct BrowserApiCallEvent {
    #[serde(default)]
    pub category: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub data: Option<BrowserApiCallEventData>,
    /// Provenance metadata identifying which producer emitted the event.
    pub source: BrowserEventSource,
    /// True if the data field was truncated due to size limits.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub truncated: Option<bool>,
    /// Event timestamp in Unix microseconds.
    #[serde(default)]
    pub ts: i64,
    #[serde(default)]
    pub r#type: String,
}

impl BrowserApiCallEvent {
    /// Create a `BrowserApiCallEvent` with the required fields set.
    #[allow(clippy::too_many_arguments, clippy::new_without_default)]
    pub fn new(ts: impl Into<i64>, source: impl Into<BrowserEventSource>) -> Self {
        Self {
            category: "control".to_owned(),
            data: None,
            source: source.into(),
            truncated: None,
            ts: ts.into(),
            r#type: "api_call".to_owned(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct BrowserApiCallEventData {
    /// Source submitted to the Playwright code-execution endpoint, capped at 8192 bytes like every other captured string. A capped value is cut on a character boundary and ends in `...\[truncated\]`. Absent for every other operation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub code: Option<String>,
    /// Wall-clock duration of the handler in milliseconds.
    #[serde(default)]
    pub duration_ms: f64,
    /// Matched route's operation, named as the in-VM API names its handler (e.g. ProcessExec, TakeScreenshot).
    #[serde(default)]
    pub operation_id: String,
    /// Per-request identifier from the in-VM API request middleware.
    #[serde(default)]
    pub request_id: String,
    /// HTTP response status code.
    #[serde(default)]
    pub status: i64,
}

impl BrowserApiCallEventData {
    /// Create a `BrowserApiCallEventData` with the required fields set.
    #[allow(clippy::too_many_arguments, clippy::new_without_default)]
    pub fn new(
        request_id: impl Into<String>,
        operation_id: impl Into<String>,
        status: impl Into<i64>,
        duration_ms: impl Into<f64>,
    ) -> Self {
        Self {
            code: None,
            duration_ms: duration_ms.into(),
            operation_id: operation_id.into(),
            request_id: request_id.into(),
            status: status.into(),
        }
    }
}

/// Provenance metadata identifying which producer emitted the event.
