/// Ordered discriminated union of Browser REPL output items.
#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(untagged)]
#[non_exhaustive]
pub enum BrowserReplContent {
    Text(BrowserReplTextContent),
    Image(BrowserReplImageContent),
    /// A value not known to this version of the SDK.
    Unknown(serde_json::Value),
}

impl<'de> serde::Deserialize<'de> for BrowserReplContent {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let value = <serde_json::Value as serde::Deserialize>::deserialize(d)?;
        let tag = value
            .get("type")
            .and_then(|t| t.as_str())
            .map(str::to_owned);
        match tag.as_deref() {
            Some("text") => serde_json::from_value(value)
                .map(Self::Text)
                .map_err(serde::de::Error::custom),
            Some("image") => serde_json::from_value(value)
                .map(Self::Image)
                .map_err(serde::de::Error::custom),
            _ => Ok(Self::Unknown(value)),
        }
    }
}

impl From<BrowserReplTextContent> for BrowserReplContent {
    fn from(v: BrowserReplTextContent) -> Self {
        Self::Text(v)
    }
}

impl From<BrowserReplImageContent> for BrowserReplContent {
    fn from(v: BrowserReplImageContent) -> Self {
        Self::Image(v)
    }
}

