/// Union type representing any managed auth event.
#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(untagged)]
#[non_exhaustive]
pub enum ManagedAuthEvent {
    ManagedAuthState(ManagedAuthStateEvent),
    Error(ErrorEvent),
    SseHeartbeat(SseHeartbeatEvent),
    /// A value not known to this version of the SDK.
    Unknown(serde_json::Value),
}

impl<'de> serde::Deserialize<'de> for ManagedAuthEvent {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let value = <serde_json::Value as serde::Deserialize>::deserialize(d)?;
        let tag = value
            .get("event")
            .and_then(|t| t.as_str())
            .map(str::to_owned);
        match tag.as_deref() {
            Some("managed_auth_state") => serde_json::from_value(value)
                .map(Self::ManagedAuthState)
                .map_err(serde::de::Error::custom),
            Some("error") => serde_json::from_value(value)
                .map(Self::Error)
                .map_err(serde::de::Error::custom),
            Some("sse_heartbeat") => serde_json::from_value(value)
                .map(Self::SseHeartbeat)
                .map_err(serde::de::Error::custom),
            _ => Ok(Self::Unknown(value)),
        }
    }
}

impl From<ManagedAuthStateEvent> for ManagedAuthEvent {
    fn from(v: ManagedAuthStateEvent) -> Self {
        Self::ManagedAuthState(v)
    }
}

impl From<ErrorEvent> for ManagedAuthEvent {
    fn from(v: ErrorEvent) -> Self {
        Self::Error(v)
    }
}

impl From<SseHeartbeatEvent> for ManagedAuthEvent {
    fn from(v: SseHeartbeatEvent) -> Self {
        Self::SseHeartbeat(v)
    }
}

